<?php declare(strict_types=1);
$pageUrl=static function(int $page) use($baseUrl,$actionFilter,$entityTypeFilter,$searchQuery):string{return $baseUrl.'/admin/audits?'.http_build_query(array_filter(['page'=>$page,'action'=>$actionFilter,'entityType'=>$entityTypeFilter,'q'=>$searchQuery],static fn(mixed $v):bool=>$v!==''));};
$json=static fn(mixed $value):string=>$value===null?'—':(string)json_encode($value,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
?>
<header class="resource-header"><div><span class="booking-eyebrow">Append-only audit</span><h1>Nhật ký hệ thống</h1><p>Dữ liệu cá nhân trong payload và địa chỉ IP đã được che trước khi hiển thị.</p></div><span class="queue-count"><strong><?= (int)$pageData['total'] ?></strong> bản ghi</span></header>
<section class="resource-surface"><form class="resource-toolbar admin-filter-bar" method="get" action="<?= $baseUrl ?>/admin/audits"><label class="toolbar-search"><svg class="app-icon"><use href="#icon-search"/></svg><span class="visually-hidden">Tìm audit</span><input name="q" value="<?= $searchQuery ?>" placeholder="RequestID, đối tượng, actor"></label><label class="toolbar-select"><span class="visually-hidden">Action</span><select name="action"><option value="">Mọi action</option><?php foreach($filterOptions['actions'] as $action):?><option value="<?= $action ?>"<?= $actionFilter===$action?' selected':'' ?>><?= $action ?></option><?php endforeach;?></select></label><label class="toolbar-select"><span class="visually-hidden">Đối tượng</span><select name="entityType"><option value="">Mọi đối tượng</option><?php foreach($filterOptions['entityTypes'] as $type):?><option value="<?= $type ?>"<?= $entityTypeFilter===$type?' selected':'' ?>><?= $type ?></option><?php endforeach;?></select></label><button class="button button--secondary button--small">Lọc</button></form><div class="audit-list"><?php foreach($pageData['items'] as $audit):?><details class="audit-entry"><summary><span><strong><?= $audit['action'] ?></strong><small><?= $audit['entityType'] ?> #<?= $audit['entityId'] ?> · <?= $audit['createdAt'] ?></small></span><span><strong><?= $audit['actorCode']??'SYSTEM' ?></strong><small><?= $audit['requestId']??'Không có RequestID' ?></small></span></summary><div class="audit-meta"><span>Actor: <?= $audit['actorName']??'Tác vụ hệ thống' ?></span><span>IP: <?= $audit['clientIp']??'—' ?></span></div><div class="audit-json-grid"><section><h3>Before</h3><pre><?= $json($audit['before']) ?></pre></section><section><h3>After</h3><pre><?= $json($audit['after']) ?></pre></section></div></details><?php endforeach;?><?php if($pageData['items']===[]):?><div class="empty-state">Không có audit phù hợp.</div><?php endif;?></div><footer class="resource-footer booking-pagination"><span>Trang <?= (int)$pageData['page'] ?> / <?= (int)$pageData['pageCount'] ?></span><span class="booking-pagination__links"><?php if($pageData['page']>1):?><a class="button button--secondary button--small" href="<?= $pageUrl((int)$pageData['page']-1) ?>">Trang trước</a><?php endif;?><?php if($pageData['page']<$pageData['pageCount']):?><a class="button button--secondary button--small" href="<?= $pageUrl((int)$pageData['page']+1) ?>">Trang sau</a><?php endif;?></span></footer></section>
